import re

def parse_numbers(parts):
    if any(re.fullmatch(r'[+-]?[0-9]+', p) is None for p in parts):
        return None
    return [int(p) for p in parts]

def evaluate(line):
    match line.split():
        case ['add', x, y]:
            values = parse_numbers([x, y])
            return None if values is None else sum(values)
        case ['neg', x]:
            values = parse_numbers([x])
            return None if values is None else -values[0]
        case ['sum', *parts]:
            values = parse_numbers(parts)
            return None if values is None else sum(values)
        case _:
            return None

def solve(data):
    return [evaluate(line) for line in data]

from dataclasses import dataclass
from math import gcd

@dataclass(frozen=True)
class Rational:
    numerator: int
    denominator: int
    def __post_init__(self):
        n, d = self.numerator, self.denominator
        if d == 0:
            raise ValueError('zero denominator')
        if d < 0:
            n, d = -n, -d
        g = gcd(n, d)
        object.__setattr__(self, 'numerator', n // g)
        object.__setattr__(self, 'denominator', d // g)
    def __add__(self, other):
        if not isinstance(other, Rational):
            return NotImplemented
        return Rational(self.numerator * other.denominator + other.numerator * self.denominator, self.denominator * other.denominator)

def solve(data):
    total = Rational(0, 1)
    for n, d in data['fractions']:
        total = total + Rational(n, d)
    return [total.numerator, total.denominator]

class IntSpan:
    def __init__(self, start, stop, step):
        if step == 0:
            raise ValueError('zero step')
        self._range = range(start, stop + (1 if step > 0 else -1), step)
    def __iter__(self):
        return iter(self._range)
    def __len__(self):
        return len(self._range)
    def __contains__(self, value):
        return value in self._range

def solve(data):
    values = IntSpan(data['start'], data['stop'], data['step'])
    return {'values': list(values), 'length': len(values), 'contains': [q in values for q in data['queries']]}
